using UnityEngine;using System.Text;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckSkyTow {
public enum SkyTowPhase{Countdown,Run,Results}
public sealed class SkyTowMatch:SportsEventSession {
 public override bool SupportsRaceCountdown=>true;public override float RaceCountdownSeconds=>Phase==SkyTowPhase.Countdown?Mathf.Max(0,3-countdown):-1;public override float RaceStartSeconds=>Phase==SkyTowPhase.Run?Age:-1;
 public SkyTowReview review;public override bool ReplayControls=>review!=null&&review.Active;public override void ExtraAction(string key)=>review?.Action(key);
 public AudioSource towEngine;public SkyTowCourse course;public SkyTowRacer[] racers;public SportsRallyViews views;public SportsChaosWeather atmosphere;public SportsWeatherPresets presets;public readonly SkyTowRules rules=new SkyTowRules();public float Age{get;private set;}public SkyTowPhase Phase{get;private set;}public int PhysicalRings{get;private set;}readonly bool[] airborne={true,true,true,true};readonly Vector3[] anchors=new Vector3[4];readonly Vector2[] errors=new Vector2[4];readonly StringBuilder labels=new StringBuilder();float countdown;
 public override string Title=>"TRUCK SKY TOW RINGS";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int OptionCount=>3;public override bool UsesAction=>false;public override bool SupportsSplitAIViews=>true;public override bool MultiViewHUD=>views!=null&&views.Humans>0&&(review==null||!review.Active);public override string OptionLabel=>new[]{"EASY","NORMAL","HARD"}[option]+" · TWO-MINUTE ARCTIC RUN";
 public override string Help=>"A POWERBOAT. A PARASAIL. SIX TONS OF TRUCK.\nA real tow cable pulls your airborne NWH truck through a120-second Arctic spline course. Left/right banks and nudges sideways. Forward/back changes wing lift for small height corrections. Gravity, wind, tow tension and actual contacts determine your path. You cannot fly freely. Your truck must fit through each ring inside the luminous route gate.100 points, gold200, clean-center+25 and explained streak bonuses up to+40. Rim overlap is a miss; these holographic course gates do not arrest your tow. Solid cliffs, water and the actual tether remain physical hazards. Misses break your streak. One result per ring. Splashdown ends your run, keeping earned ring points. Highest actual score wins; exact ties share victory.\nFour independent simultaneous courses use the same route, physics, wind and control limits. Difficulty changes AI reaction and aiming precision, never launch power or scores. Show AI Cameras defaults OFF; AI-only retains a broadcast view. Pause/reconnect preserves your flight. Rematch restores every ring and tow. Offline only.";
 public override string Header=>Title+" · "+course.sections[Mathf.Clamp((int)(Age/20),0,5)]+" · "+atmosphere.Description;
 public override string Status=>review!=null&&review.Active?"RECORDED FLIGHT · "+review.motion.Speed.ToString("F2")+"× · CAMERA "+(review.motion.Angle+1):Phase==SkyTowPhase.Countdown?"READY · "+Mathf.Max(1,Mathf.CeilToInt(3-countdown)):"AIR CONTROL · LEFT/RIGHT BANK · FORWARD/BACK LIFT · "+Mathf.Max(0,120-Age).ToString("F0")+"s";
 public override string Standings{get{labels.Clear();for(int i=0;i<setup.count;i++)labels.Append(setup.players[i].name).Append("  ").Append(rules.score[i]).Append(" PTS · ").Append(rules.hits[i]).Append(" /36 RINGS\n");return labels.ToString();}}
 public override string Results{get{labels.Clear();for(int i=0;i<setup.count;i++)if(rules.winners[i])labels.Append(setup.players[i].name).Append("  ");return labels+"WIN THE ARCTIC RUN!\n\n"+Standings;}}
 public override bool TryReadScoreCard(int i,out string value,out string detail){value=rules.score[i].ToString();detail=rules.hits[i]+"/36 RINGS · "+(rules.finished[i]?"FINISHED":"STREAK "+rules.streak[i]);return true;}
 protected override void BeginGame(){int seed=UnityEngine.Random.Range(1,1000000);atmosphere.ConfigurePreset(presets.Resolve(seed),seed);rules.Start(setup.count,36);PhysicalRings=0;Age=countdown=0;Phase=SkyTowPhase.Countdown;for(int i=0;i<4;i++){racers[i].gameObject.SetActive(i<setup.count);racers[i].boat.gameObject.SetActive(i<setup.count);if(i<setup.count){racers[i].Prepare();errors[i]=new Vector2(UnityEngine.Random.Range(-1f,1f),UnityEngine.Random.Range(-1f,1f));}for(int r=0;r<36;r++){var ring=course.Ring(i,r);ring.gameObject.SetActive(i<setup.count);ring.ResetRing();}}views.Restore();review?.ResetRecord();}
 Vector2 AI(int slot){int next=0;while(next<36&&rules.outcomes[slot,next]!=0)next++;var body=racers[slot].truck.body;var r=racers[slot];course.Frame(Age,slot,out var p,out var q);var nominal=course.NominalTruck(Age,slot);var target=nominal;target.y-=r.truck.shape.center.y;if(next<36){var ring=course.Ring(slot,next);var offset=ring.transform.position-course.NominalTruck(ring.at,slot);target+=offset*Mathf.Clamp01(1-(ring.at-Age)/5);}float skill=(int)setup.players[slot].difficulty;float noise=Mathf.Lerp(2.4f,.3f,skill*.5f);target+=q*Vector3.right*(errors[slot].x*noise*Mathf.Sin(Age*.65f+slot));target.y+=errors[slot].y*noise;var desiredVelocity=(course.NominalTruck(Age+.1f,slot)-nominal)*10;var right=q*Vector3.right;float error=Vector3.Dot(target-body.position,right),velocityError=Vector3.Dot(desiredVelocity-body.linearVelocity,right);float x=(error*.8f+velocityError*.9f)/r.controlAcceleration;float airspeed=Mathf.Max(1,Vector3.ProjectOnPlane(body.linearVelocity-atmosphere.Flow,Vector3.up).magnitude);float desiredLift=Physics.gravity.magnitude+.5f+(target.y-body.position.y)*.8f-body.linearVelocity.y*1.6f;float y=(desiredLift/Mathf.Max(.01f,SkyTowAero.Neutral(airspeed,course.Cruise,Physics.gravity.magnitude))-1)/r.liftControlRange;return new Vector2(Mathf.Clamp(x,-1,1),Mathf.Clamp(y,-1,1));}
 protected override void Simulate(float dt){atmosphere.Tick(Time.time);if(Phase==SkyTowPhase.Countdown){countdown+=dt;if(countdown>=3){Phase=SkyTowPhase.Run;foreach(var r in racers)if(r.gameObject.activeSelf)r.Release();}return;}if(Phase!=SkyTowPhase.Run)return;Age+=dt;for(int i=0;i<setup.count;i++)racers[i].Step(Age,setup.players[i].source==BowlingSource.AI?AI(i):commands[i],dt);review?.Record(Age);if(rules.Complete){Phase=SkyTowPhase.Results;EndMatch();}}
 public void RingResolved(int slot,bool success,bool bonus){if(success)PhysicalRings++;feedback.Play(success?bonus?5:4:3,0,true);Pulse(slot,success?.1f:.04f,.08f);}
 public override string ViewText(int v){int i=views.owners[v];return setup.players[i].name+" · "+rules.score[i]+" PTS\n"+rules.hits[i]+" /36 RINGS · "+racers[i].Reaction+"\n"+(racers[i].truck.body.linearVelocity.magnitude*2.236936f).ToString("F0")+" MPH · "+Mathf.Max(0,120-Age).ToString("F0")+"s";}
 protected override void Present(float dt){if(views==null||racers==null)return;if(review!=null&&review.Active){review.Step(dt);return;}if(towEngine!=null){towEngine.volume=Live&&Phase==SkyTowPhase.Run?settings.sfx*.07f:0;towEngine.pitch=.85f+Mathf.Sin(Age*.4f)*.03f;if(towEngine.volume>0&&!towEngine.isPlaying)towEngine.Play();else if(towEngine.volume<=0)towEngine.Stop();}for(int i=0;i<setup.count;i++){anchors[i]=racers[i].truck.body.position;racers[i].Present();}views.Focus=0;for(int i=0;i<setup.count;i++)if(!rules.finished[i]){views.Focus=i;break;}views.Follow(dt,airborne,anchors);if(views.Humans==0){int slot=views.Focus;course.Frame(Age,slot,out var point,out var rotation);views.broadcast.Pose(anchors[slot]+rotation*Vector3.forward*7+Vector3.up,rotation*new Vector3(0,7,-24),72);}else for(int view=0;view<views.Humans;view++){int slot=views.owners[view];course.Frame(Age,slot,out var point,out var rotation);views.views[view].Pose(anchors[slot]+rotation*Vector3.forward*7+Vector3.up,rotation*new Vector3(0,6,-22),72);}}
 protected override void StopGame(){review?.Stop(false);if(racers!=null)foreach(var r in racers)r.Stop();}protected override void StopSounds(){if(towEngine!=null)towEngine.Stop();if(racers!=null)foreach(var r in racers)r.truck.StopSound();}protected override void SetPaused(bool paused){atmosphere?.Pause(paused);if(towEngine!=null){if(paused)towEngine.Pause();else towEngine.UnPause();}}
}
}
